1	// Wrapper de streaming SSE para a edge function MIA com instrumentação OpenTelemetry
2	// Extraído de src/shared/contexts/MiaContext.tsx → src/features/mia/api/callLLMStream.ts
3	
4	import { supabase } from '@/integrations/supabase/client';
5	import type { MiaStreamEvent } from '@/types/mia';
6	import { MiaLLMError, MIA_ERROR_CODES } from '@/features/mia/lib/errors';
7	import { readSseStream } from '@/features/mia/lib/streaming';
8	import { isInitialized, getTelemetryConfig } from '@/shared/lib/telemetry/telemetry';
9	import {
10	  initMiaMetrics,
11	  recordMiaRequest,
12	  recordMiaToolCall,
13	  recordMiaAgentDuration,
14	  recordMiaFallbackActivation,
15	} from '@/features/mia/lib/miaMetrics';
16	
17	const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL || '';
18	const SUPABASE_ANON_KEY = import.meta.env.VITE_SUPABASE_ANON_KEY || '';
19	
20	// ---------------------------------------------------------------------------
21	// Tipos internos para OTel (importados dinamicamente)
22	// ---------------------------------------------------------------------------
23	
24	type OtelSpan = import('@opentelemetry/api').Span;
25	type OtelTracer = import('@opentelemetry/api').Tracer;
26	type OtelContext = import('@opentelemetry/api').Context;
27	
28	/**
29	 * Invoca a edge function MIA via Server-Sent Events (SSE).
30	 * Emite eventos tipados conforme MiaStreamEvent à medida que chegam.
31	 *
32	 * Instrumentação OTel:
33	 * - Span raiz  `mia.agent.invoke` com atributos: domain, round, model, fallback_level, user.role, store.id
34	 * - Span filho `mia.tool.call` para cada tool call com: tool.name, tool.parallel, tool.duration_ms
35	 * - Eventos `mia.streaming.start` e `mia.streaming.end` no span raiz
36	 * - Métricas: mia_requests_total, mia_tool_calls_total, mia_agent_duration_ms, mia_fallback_activations_total
37	 *
38	 * @throws MiaLLMError com código INFRA_EDGE_FUNCTION quando não autenticado ou HTTP error
39	 */
40	export async function callLLMStream(
41	  body: Record<string, unknown>,
42	  onEvent: (event: MiaStreamEvent) => void,
43	  signal?: AbortSignal,
44	): Promise<void> {
45	  // Inicializa métricas MIA (idempotente)
46	  await initMiaMetrics();
47	
48	  // Extrai metadados para atributos do span
49	  const pageContext = body.page_context as Record<string, unknown> | undefined;
50	  const domain = String(pageContext?.domain_hint ?? 'UNKNOWN');
51	  const storeId = String(pageContext?.store_id ?? '');
52	  const userProfile = pageContext?.user_profile as Record<string, unknown> | undefined;
53	  const userRole = String(userProfile?.role ?? '');
54	  const startTime = Date.now();
55	
56	  // Sem OTel habilitado — executa diretamente sem spans
57	  if (!isInitialized() || !getTelemetryConfig().enabled) {
58	    return _executeStream(body, domain, onEvent, signal, startTime, null, null, null);
59	  }
60	
61	  // Obtém tracer e cria span raiz via startActiveSpan (propaga contexto para filhos)
62	  const { trace: otelTrace, context: otelContext } = await import('@opentelemetry/api');
63	  const cfg = getTelemetryConfig();
64	  const tracer = otelTrace.getTracer(cfg.serviceName, cfg.serviceVersion);
65	
66	  return tracer.startActiveSpan(
67	    'mia.agent.invoke',
68	    {
69	      attributes: {
70	        'mia.agent.domain': domain,
71	        'mia.agent.round': '0',
72	        'mia.llm.model': 'unknown',
73	        'mia.llm.fallback_level': '0',
74	        'mia.store.id': storeId,
75	        'mia.user.role': userRole,
76	      },
77	    },
78	    async (rootSpan) => {
79	      // Captura contexto com o span raiz ativo para parenting dos spans filhos
80	      const spanContext = otelContext.active();
81	      return _executeStream(body, domain, onEvent, signal, startTime, rootSpan, tracer, spanContext);
82	    },
83	  );
84	}
85	
86	// ---------------------------------------------------------------------------
87	// Implementação interna do stream com suporte opcional a spans OTel
88	// ---------------------------------------------------------------------------
89	
90	async function _executeStream(
91	  body: Record<string, unknown>,
92	  domain: string,
93	  onEvent: (event: MiaStreamEvent) => void,
94	  signal: AbortSignal | undefined,
95	  startTime: number,
96	  rootSpan: OtelSpan | null,
97	  tracer: OtelTracer | null,
98	  spanContext: OtelContext | null,
99	): Promise<void> {
100	  let llmModel = 'unknown';
101	
102	  // Mapa de spans de tools em aberto: stepIndex → { span, startMs }
103	  type ToolInfo = { span: OtelSpan; startMs: number };
104	  const toolSpanMap = new Map<number, ToolInfo>();
105	
106	  // Emite evento de início do streaming no span raiz
107	  rootSpan?.addEvent('mia.streaming.start');
108	
109	  // Cria onEvent instrumentado para interceptar step events e criar spans filhos
110	  const instrumentedOnEvent = (event: MiaStreamEvent): void => {
111	    if (rootSpan && tracer && event.type === 'step' && event.step) {
112	      const step = event.step;
113	      const stepData = (step.data ?? {}) as Record<string, unknown>;
114	
115	      // Atualiza atributos do span raiz com info server-side (model, fallback, round)
116	      if (stepData.model) {
117	        llmModel = String(stepData.model);
118	        rootSpan.setAttribute('mia.llm.model', llmModel);
119	      }
120	      if (stepData.fallback_level !== undefined) {
121	        const lvl = String(stepData.fallback_level);
122	        rootSpan.setAttribute('mia.llm.fallback_level', lvl);
123	        if (Number(stepData.fallback_level) > 0) {
124	          recordMiaFallbackActivation(lvl, { 'mia.agent.domain': domain });
125	        }
126	      }
127	      if (stepData.round !== undefined) {
128	        rootSpan.setAttribute('mia.agent.round', String(stepData.round));
129	      }
130	
131	      // Rastreamento de tool calls por ciclo de vida do step (running → success/error)
132	      if (step.status === 'running' && !toolSpanMap.has(step.index)) {
133	        const toolSpan = tracer.startSpan(
134	          'mia.tool.call',
135	          {
136	            attributes: {
137	              'mia.tool.name': step.action_type,
138	              'mia.tool.parallel': 'false',
139	            },
140	          },
141	          spanContext ?? undefined,
142	        );
143	        toolSpanMap.set(step.index, { span: toolSpan, startMs: Date.now() });
144	      } else if (
145	        (step.status === 'success' || step.status === 'error') &&
146	        toolSpanMap.has(step.index)
147	      ) {
148	        const info = toolSpanMap.get(step.index)!;
149	        const durMs = Date.now() - info.startMs;
150	        info.span.setAttribute('mia.tool.duration_ms', String(durMs));
151	        if (step.status === 'error') {
152	          const errMsg = step.error_message ?? `${step.action_type} falhou`;
153	          info.span.setStatus({ code: 2, message: errMsg });
154	          info.span.recordException(new Error(errMsg));
155	        } else {
156	          info.span.setStatus({ code: 1 });
157	        }
158	        info.span.end();
159	        toolSpanMap.delete(step.index);
160	        recordMiaToolCall(step.action_type, { 'mia.agent.domain': domain });
161	      }
162	    }
163	    onEvent(event);
164	  };
165	
166	  // Autenticação
167	  const session = await supabase.auth.getSession();
168	  const token = session.data.session?.access_token;
169	  if (!token) {
170	    if (rootSpan) {
171	      rootSpan.setStatus({ code: 2, message: MIA_ERROR_CODES.INFRA_EDGE_FUNCTION });
172	      rootSpan.end();
173	    }
174	    throw new MiaLLMError({
175	      code: MIA_ERROR_CODES.INFRA_EDGE_FUNCTION,
176	      message: 'Não autenticado: sessão ausente',
177	      userMessage: 'Sessão expirada. Faça login novamente.',
178	    });
179	  }
180	
181	  const response = await fetch(`${SUPABASE_URL}/functions/v1/mia`, {
182	    method: 'POST',
183	    headers: {
184	      Authorization: `Bearer ${token}`,
185	      'Content-Type': 'application/json',
186	      apikey: SUPABASE_ANON_KEY,
187	    },
188	    body: JSON.stringify({ ...body, stream: true }),
189	    signal,
190	  });
191	
192	  if (!response.ok) {
193	    if (rootSpan) {
194	      rootSpan.setStatus({ code: 2, message: MIA_ERROR_CODES.INFRA_EDGE_FUNCTION });
195	      rootSpan.end();
196	    }
197	    throw new MiaLLMError({
198	      code: MIA_ERROR_CODES.INFRA_EDGE_FUNCTION,
199	      message: `HTTP ${response.status}`,
200	      userMessage: 'Erro ao conectar com a MIA. Tente novamente.',
201	    });
202	  }
203	  if (!response.body) {
204	    if (rootSpan) {
205	      rootSpan.setStatus({ code: 2, message: MIA_ERROR_CODES.INFRA_STREAMING_PARSE });
206	      rootSpan.end();
207	    }
208	    throw new MiaLLMError({
209	      code: MIA_ERROR_CODES.INFRA_STREAMING_PARSE,
210	      message: 'Sem corpo na resposta da edge function',
211	    });
212	  }
213	
214	  try {
215	    await readSseStream(response.body, instrumentedOnEvent);
216	  } catch (err) {
217	    // Fecha spans de tools ainda abertos
218	    for (const [, info] of toolSpanMap) {
219	      info.span.setStatus({ code: 2, message: 'stream interrompido' });
220	      info.span.end();
221	    }
222	    if (rootSpan) {
223	      rootSpan.setStatus({ code: 2, message: MIA_ERROR_CODES.INFRA_STREAMING_PARSE });
224	      rootSpan.recordException(err instanceof Error ? err : new Error(String(err)));
225	      rootSpan.end();
226	    }
227	    recordMiaRequest(domain, llmModel, 'error');
228	    throw err;
229	  }
230	
231	  // Stream concluído com sucesso
232	  rootSpan?.addEvent('mia.streaming.end');
233	  rootSpan?.setStatus({ code: 1 }); // OK
234	  rootSpan?.end();
235	
236	  const durationMs = Date.now() - startTime;
237	  recordMiaRequest(domain, llmModel, 'success');
238	  recordMiaAgentDuration(domain, durationMs);
239	}
