1	// Hook principal da feature MIA — contém toda a lógica do Provider
2	// MiaContext.tsx importa este hook e o re-expõe via Context (thin wrapper)
3	
4	import React, { useState, useCallback, useRef, useEffect } from 'react';
5	import { useLocation, useNavigate } from 'react-router-dom';
6	import { useStore } from '@/shared/contexts/StoreContext';
7	import { useAuth } from '@/hooks/useAuth';
8	import { usePermissions } from '@/shared/hooks/usePermissions';
9	import { supabase } from '@/integrations/supabase/client';
10	import { callLLMStream } from '@/features/mia/api/callLLMStream';
11	import { generateId } from '@/shared/lib/generateId';
12	import { fetchPendingProactive, markProactiveDelivered, formatProactiveGreeting } from '@/features/mia/api/proactiveQueue';
13	import { ensureProactiveConfig } from '@/features/mia/lib/proactiveConfig';
14	import {
15	  listUserConversations,
16	  loadConversationMessagesFromDB,
17	  deleteConversationInDB,
18	  setConversationTitle,
19	  type ConversationMeta,
20	} from '@/features/mia/api/conversationRepo';
21	import { toast } from 'sonner';
22	import { wideWarn } from '@/shared/lib/telemetry/wide-events';
23	import { handleError } from '@/shared/lib/error-handler';
24	import type {
25	  MiaChatMessage,
26	  MiaAction,
27	  MiaPageContext,
28	  MiaWebResponse,
29	  MiaActionHandler,
30	  MiaScreenState,
31	  MiaActionResult,
32	  MiaTaskPlan,
33	  MiaTaskItem,
34	  MiaUserProfile,
35	  MiaStreamEvent,
36	  MiaExecutionStep,
37	} from '@/types/mia';
38	
39	// ============================================================================
40	// CONVERSATION PERSISTENCE — localStorage para índice e mensagens
41	// ============================================================================
42	
43	const CONV_INDEX_KEY = 'mia_conversations';
44	const CONV_MSG_PREFIX = 'mia_conv_';
45	const ACTIVE_KEY = 'mia_active_conv';
46	const OPEN_KEY = 'mia_panel_open';
47	
48	export interface MiaConversation {
49	  id: string;
50	  title: string;
51	  createdAt: string;
52	  updatedAt: string;
53	  messageCount: number;
54	}
55	
56	function loadConversations(): MiaConversation[] {
57	  try {
58	    const raw = localStorage.getItem(CONV_INDEX_KEY);
59	    return raw ? JSON.parse(raw) : [];
60	  } catch { return []; }
61	}
62	
63	function saveConversations(convs: MiaConversation[]) {
64	  try { localStorage.setItem(CONV_INDEX_KEY, JSON.stringify(convs)); } catch {}
65	}
66	
67	function loadConversationMessages(convId: string): MiaChatMessage[] {
68	  try {
69	    const raw = localStorage.getItem(CONV_MSG_PREFIX + convId);
70	    if (!raw) return [];
71	    return JSON.parse(raw).map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) }));
72	  } catch { return []; }
73	}
74	
75	// Comprime histórico para localStorage: >10 msgs → mantém 6 recentes + 1 placeholder de compressão
76	function compressHistory(msgs: MiaChatMessage[]): MiaChatMessage[] {
77	  if (msgs.length <= 10) return msgs;
78	  const recent = msgs.slice(-6);
79	  const olderCount = msgs.length - 6;
80	  const summaryMsg: MiaChatMessage = {
81	    id: 'history-summary',
82	    role: 'assistant',
83	    content: `[${olderCount} mensagens anteriores comprimidas para economizar espaço]`,
84	    timestamp: msgs[0]?.timestamp || new Date(),
85	  };
86	  return [summaryMsg, ...recent];
87	}
88	
89	function saveConversationMessages(convId: string, messages: MiaChatMessage[]) {
90	  try {
91	    // Mensagens proativas são efêmeras (saudação ao abrir) — não persistem.
92	    const toSave = compressHistory(messages.filter(m => !m.isProactive));
93	    const serialized = toSave.map(m => ({
94	      id: m.id, role: m.role, content: m.content,
95	      actions: m.actions, actionsExecuted: m.actionsExecuted,
96	      thinkingBlocks: m.thinkingBlocks,
97	      agentRounds: m.agentRounds,
98	      executionStepsSnapshot: m.executionStepsSnapshot,
99	      watchLogSnapshot: m.watchLogSnapshot,
100	      clarification: m.clarification,
101	      timestamp: m.timestamp.toISOString(),
102	    }));
103	    localStorage.setItem(CONV_MSG_PREFIX + convId, JSON.stringify(serialized));
104	  } catch {}
105	}
106	
107	function deleteConversationMessages(convId: string) {
108	  try { localStorage.removeItem(CONV_MSG_PREFIX + convId); } catch {}
109	}
110	
111	function getActiveConvId(): string | null {
112	  try { return localStorage.getItem(ACTIVE_KEY); } catch { return null; }
113	}
114	
115	function setActiveConvId(id: string) {
116	  try { localStorage.setItem(ACTIVE_KEY, id); } catch {}
117	}
118	
119	function getIsOpen(): boolean {
120	  try { return localStorage.getItem(OPEN_KEY) === '1'; } catch { return false; }
121	}
122	
123	function setIsOpenStorage(open: boolean) {
124	  try { localStorage.setItem(OPEN_KEY, open ? '1' : '0'); } catch {}
125	}
126	
127	// ============================================================================
128	// MODULE VISIT TRACKING — rastreia primeira visita para onboarding
129	// ============================================================================
130	
131	const MODULE_VISITS_KEY = 'mia_module_visits';
132	
133	function loadModuleVisits(): Record<string, { count: number; first_visit: string; last_visit: string }> {
134	  try {
135	    const raw = localStorage.getItem(MODULE_VISITS_KEY);
136	    return raw ? JSON.parse(raw) : {};
137	  } catch { return {}; }
138	}
139	
140	function trackModuleVisit(route: string) {
141	  try {
142	    const visits = loadModuleVisits();
143	    const now = new Date().toISOString().split('T')[0];
144	    const existing = visits[route];
145	    visits[route] = {
146	      count: (existing?.count || 0) + 1,
147	      first_visit: existing?.first_visit || now,
148	      last_visit: now,
149	    };
150	    localStorage.setItem(MODULE_VISITS_KEY, JSON.stringify(visits));
151	  } catch {}
152	}
153	
154	function buildUserProfile(user: any, route: string): MiaUserProfile {
155	  const visits = loadModuleVisits();
156	  const totalVisits = Object.values(visits).reduce((sum, v) => sum + v.count, 0);
157	
158	  let role: MiaUserProfile['role'] = 'unknown';
159	  const userRole = user?.user_metadata?.role || user?.app_metadata?.role || '';
160	  if (userRole === 'admin' || userRole === 'super_admin') role = 'admin';
161	  else if (userRole === 'gerente' || userRole === 'manager') role = 'gerente';
162	  else if (userRole === 'operador' || userRole === 'operator') role = 'operador';
163	  else if (userRole === 'diretoria' || userRole === 'director') role = 'diretoria';
164	
165	  let expertise_level: MiaUserProfile['expertise_level'] = 'beginner';
166	  if (totalVisits > 50) expertise_level = 'advanced';
167	  else if (totalVisits > 15) expertise_level = 'intermediate';
168	
169	  return {
170	    role,
171	    name: user?.user_metadata?.full_name || user?.user_metadata?.name || undefined,
172	    expertise_level,
173	    module_visits: visits,
174	  };
175	}
176	
177	// ============================================================================
178	// TIPO PÚBLICO DO HOOK
179	// ============================================================================
180	
181	export interface UseMiaReturn {
182	  isOpen: boolean;
183	  setIsOpen: (open: boolean) => void;
184	  messages: MiaChatMessage[];
185	  // Novo nome (spec US-024)
186	  isStreaming: boolean;
187	  // Alias legado mantido para não quebrar consumers existentes
188	  isLoading: boolean;
189	  sendMessage: (text: string) => Promise<void>;
190	  clearHistory: () => void;
191	  registerActions: (route: string, handlers: Record<string, MiaActionHandler>) => void;
192	  unregisterActions: (route: string) => void;
193	  executeActions: (actions: MiaAction[]) => Promise<void>;
194	  getPageContext: () => MiaPageContext;
195	  setScreenState: (state: Partial<MiaScreenState>) => void;
196	  sessionId: string;
197	  pendingConfirmation: { actions: MiaAction[]; messageId: string } | null;
198	  confirmPendingActions: () => Promise<void>;
199	  cancelPendingActions: () => void;
200	  // Gerenciamento de conversas
201	  conversations: MiaConversation[];
202	  activeConversationId: string;
203	  startNewConversation: () => void;
204	  switchConversation: (id: string) => void;
205	  deleteConversation: (id: string) => void;
206	  // Task plan (preview → approve → execute)
207	  activeTaskPlan: MiaTaskPlan | null;
208	  approveTaskPlan: () => Promise<void>;
209	  editTaskPlanItem: (index: number, newData: Record<string, any>) => void;
210	  cancelTaskPlan: () => void;
211	  // Clarification (ask_clarification — espelha AskUserQuestion do Claude Code)
212	  answerClarification: (messageId: string, value: string, label?: string) => Promise<void>;
213	  // Status de streaming
214	  streamingStatus: string | null;
215	  streamingText: string;
216	  // Agent loop
217	  executionSteps: MiaExecutionStep[];
218	  agentRounds: import('@/types/mia').MiaAgentRound[];
219	  thinkingBlocks: { round: number; content: string; durationMs: number }[];
220	  // Novo nome (spec US-024)
221	  abortStream: () => void;
222	  // Alias legado mantido para não quebrar consumers existentes
223	  cancelMessage: () => void;
224	  // Raw mode — IA sem sistema MIA (sem system prompt, sem tools, sem actions)
225	  rawMode: boolean;
226	  setRawMode: (enabled: boolean) => void;
227	  rawModeOptions: { webSearch: boolean; reasoning: boolean };
228	  setRawModeOptions: (opts: { webSearch?: boolean; reasoning?: boolean }) => void;
229	}
230	
231	// ============================================================================
232	// HOOK PRINCIPAL — toda a lógica do MiaProvider extraída aqui
233	// ============================================================================
234	
235	export function useMia(): UseMiaReturn {
236	  const [conversations, setConversations] = useState<MiaConversation[]>(loadConversations);
237	
238	  const [activeConversationId, setActiveConversationId] = useState<string>(() => {
239	    const saved = getActiveConvId();
240	    if (saved && loadConversations().some(c => c.id === saved)) return saved;
241	    return generateId();
242	  });
243	
244	  const [messages, setMessages] = useState<MiaChatMessage[]>(() =>
245	    loadConversationMessages(getActiveConvId() || '')
246	  );
247	  const [isOpen, setIsOpenRaw] = useState(getIsOpen);
248	  const [isStreaming, setIsStreaming] = useState(false);
249	  const [pendingConfirmation, setPendingConfirmation] = useState<{
250	    actions: MiaAction[];
251	    messageId: string;
252	  } | null>(null);
253	
254	  const [activeTaskPlan, setActiveTaskPlan] = useState<MiaTaskPlan | null>(null);
255	  const [streamingStatus, setStreamingStatus] = useState<string | null>(null);
256	  const [streamingText, setStreamingText] = useState<string>('');
257	  const [executionSteps, setExecutionSteps] = useState<MiaExecutionStep[]>([]);
258	  const [agentRounds, setAgentRounds] = useState<import('@/types/mia').MiaAgentRound[]>([]);
259	  const [thinkingBlocks, setThinkingBlocks] = useState<{ round: number; content: string; durationMs: number; startTime?: number }[]>([]);
260	  const [rawMode, setRawMode] = useState(false);
261	  const [rawModeOptions, setRawModeOptionsState] = useState<{ webSearch: boolean; reasoning: boolean }>({ webSearch: false, reasoning: false });
262	  const tokenBufferRef = useRef<string[]>([]);
263	  const rafRef = useRef<number | null>(null);
264	  const abortControllerRef = useRef<AbortController | null>(null);
265	  const actionRegistryRef = useRef<Record<string, Record<string, MiaActionHandler>>>({});
266	  const screenStateRef = useRef<Partial<MiaScreenState>>({});
267	  const recentActionsRef = useRef<MiaActionResult[]>([]);
268	  // Snapshots síncronos pra evitar closure stale ao salvar mensagem persistente.
269	  // setState é async — ler `agentRounds`/`thinkingBlocks` no `finally` pega
270	  // valor antigo da closure. Refs garantem leitura do estado atual no momento
271	  // do snapshot pra não perder passos quando msg vira persistente.
272	  const turnAgentRoundsRef = useRef<import('@/types/mia').MiaAgentRound[]>([]);
273	  const turnThinkingBlocksRef = useRef<{ round: number; content: string; durationMs: number }[]>([]);
274	  const turnExecutionStepsRef = useRef<MiaExecutionStep[]>([]);
275	
276	  const location = useLocation();
277	  const navigate = useNavigate();
278	  const { selectedStore } = useStore();
279	  const { user } = useAuth();
280	
281	  // Expõe user_id globalmente para o renderer de markdown (link click tracking)
282	  React.useEffect(() => {
283	    if (user?.id) (window as any).__mia_user_id = user.id;
284	  }, [user?.id]);
285	
286	  const {
287	    isAdmin, hasPermission,
288	    canViewFinanceiro, canViewEstoque, canViewNotasFiscais,
289	    canViewLogistica, canViewRequisicao, canViewEncomendas,
290	    canViewProntaEntrega, canViewEventos, canViewNCM,
291	  } = usePermissions();
292	
293	  // ── Verificação de permissões para ações MIA ───────────────
294	
295	  const canAccessRoute = useCallback((route: string): boolean => {
296	    if (isAdmin()) return true;
297	    if (route.includes('financeiro') || route.includes('notas-fiscais') || route.includes('consultar-ncm')) {
298	      if (route.includes('notas-fiscais')) return canViewNotasFiscais();
299	      if (route.includes('consultar-ncm')) return canViewNCM();
300	      return canViewFinanceiro();

