418	          const byId = new Map<string, MiaConversation>(prev.map(c => [c.id, c]));
419	          for (const dbc of dbConvs) {
420	            byId.set(dbc.id, {
421	              id: dbc.id,
422	              title: dbc.title,
423	              createdAt: dbc.createdAt,
424	              updatedAt: dbc.updatedAt,
425	              messageCount: Math.max(dbc.messageCount, byId.get(dbc.id)?.messageCount ?? 0),
426	            });
427	          }
428	          return [...byId.values()].sort(
429	            (a, b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime()
430	          );
431	        });
432	
433	        // Se a activeConversationId local não existe no DB, é uma conv local
434	        // sem persistência. Em fresh device é o caso comum. Switcha pra latest.
435	        if (opts?.switchToLatestIfMissing) {
436	          const activeIsInDb = dbConvs.some(c => c.id === activeConversationId);
437	          const localHasMessages = messages.length > 0;
