457	            const withProactive = (msgs: MiaChatMessage[]) =>
458	              proactive.length && !msgs.some(m => m.isProactive) ? [...proactive, ...msgs] : msgs;
459	            const currentReal = current.filter(m => !m.isProactive);
460	            if (dbMsgs.length > currentReal.length) return withProactive(dbMsgs);
461	            const lastDb = dbMsgs[dbMsgs.length - 1]?.timestamp?.getTime() ?? 0;
462	            const lastLocal = currentReal[currentReal.length - 1]?.timestamp?.getTime() ?? 0;
463	            if (lastDb > lastLocal) return withProactive(dbMsgs);
