97	  thinkingBlocks,
98	  agentRounds,
99	  executionSteps,
100	  activeTaskPlan,
101	  pendingConfirmation,
102	  onConfirm,
103	  onCancelConfirm,
104	  onApproveTask,
105	  onCancelTask,
106	  onClarificationAnswer,
107	  emptyState
108	}: MiaMessageListProps) {
109	  const scrollRef = useRef<HTMLDivElement>(null);
110	
111	  // Auto-scroll para o final em novos conteúdos
112	  useEffect(() => {
113	    if (scrollRef.current) {
114	      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
115	    }
116	  }, [messages, isStreaming, streamingText, streamingStatus, thinkingBlocks, agentRounds, executionSteps]);
117	
118	  if (messages.length === 0 && !isStreaming) {
119	    return (
120	      <div className="flex-1 overflow-y-auto overflow-x-hidden scroll-smooth scrollbar-thin scrollbar-thumb-[--mia-glass-border] hover:scrollbar-thumb-[--mia-accent]/20">
121	        {emptyState}
122	      </div>
123	    );
124	  }
125	
126	  return (
127	    <div 
128	      ref={scrollRef}
129	      className="flex-1 overflow-y-auto overflow-x-hidden scroll-smooth scrollbar-thin scrollbar-thumb-[--mia-glass-border] hover:scrollbar-thumb-[--mia-accent]/20"
130	    >
131	      <div className="max-w-2xl mx-auto px-4 sm:px-6 pt-8 pb-36">
132	        <AnimatePresence initial={false}>
133	          {/* Mensagens concluídas */}
134	          {messages.map((m, i) => (
135	            <MemoizedBubble
136	              key={m.id || i}
137	              message={m}
138	              isLast={i === messages.length - 1 && !isStreaming}
139	              onClarificationAnswer={onClarificationAnswer}
140	            />
141	          ))}
142	
143	          {/* ── STREAMING: Uma única MiaStreamingMessage enquanto isStreaming === true ── */}
144	          {isStreaming && (
145	            <MiaStreamingMessage
146	              key="streaming-message"
147	              streamingText={streamingText}
148	              streamingStatus={streamingStatus}
149	              thinkingBlocks={thinkingBlocks}
150	              agentRounds={agentRounds}
151	              executionSteps={executionSteps}
152	            />
153	          )}
154	
155	          {/* Interactive UI Cards */}
156	          {pendingConfirmation && (
157	            <ConfirmationCard 
158	              key="pending-confirmation"
159	              actions={pendingConfirmation.actions} 
160	              onConfirm={onConfirm} 
161	              onCancel={onCancelConfirm} 
162	            />
163	          )}
164	
165	          {activeTaskPlan && (
166	            <TaskPlanCard 
167	              key="active-task-plan"
168	              plan={activeTaskPlan} 
169	              onApprove={onApproveTask} 
170	              onCancel={onCancelTask} 
171	            />
172	          )}
173	        </AnimatePresence>
174	      </div>
175	    </div>
176	  );
177	}
